input.sparql:
SELECT ?zone ?point ?pointClass ?ts WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_ZN_2" .
  ?point brick:hasProperty ?point .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?point ?ts ?p1 ?p2 WHERE {
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point a ?p1 }
  OPTIONAL { ?point rdfs:label ?p2 }
}

SELECT ?point ?label ?zone ?ts WHERE {
  ?point a brick:Occupancy_Sensor .
  OPTIONAL { ?point rdfs:label ?label }
  OPTIONAL { ?z brick:hasSensor ?point ; rdfs:label ?zone }
  ?point ref:hasTimeseriesId ?ts .
}

